#include <stdio.h>

int main() {
    int digits[] = {1, 0, 2, 1, 0, 1, 2, 2};
    int counts[3] = {0};
    for (int i = 0; i < 8; i++) {
        counts[digits[i]]++;
    }
    for (int v = 0; v < 3; v++) {
        printf("%d:%d\n", v, counts[v]);
    }
    return 0;
}
